WAV header (44 bytes little-endian):
```
offset  size  field
0       4     "RIFF"
4       4     riffSize = 36 + dataSize
8       4     "WAVE"
12      4     "fmt "
16      4     16
20      2     1 (PCM)
22      2     channels
24      4     sampleRate
28      4     byteRate = rate*channels*bits/8
32      2     blockAlign = channels*bits/8
34      2     bitsPerSample
36      4     "data"
40      4     dataSize
```

Let me write helpers using explicit byte stores to avoid alignment/packing issues:

```c
static void put_le32(uint8_t *p, uint32_t v) { p[0]=v&0xff; p[1]=(v>>8)&0xff; p[2]=(v>>16)&0xff; p[3]=(v>>24)&0xff; }
static void put_le16(uint8_t *p, uint16_t v) { p[0]=v&0xff; p[1]=(v>>8)&0xff; }
static uint32_t get_le32(const uint8_t *p) { return p[0] | (p[1]<<8) | (p[2]<<16) | ((uint32_t)p[3]<<24); }
static uint16_t get_le16(const uint8_t *p) { return p[0] | (p[1]<<8); }

static void wav_write_header(uint8_t *h, uint32_t data_size, uint16_t channels, uint32_t rate, uint16_t bits)
{
    memcpy(h, "RIFF", 4);
    put_le32(h+4, 36 + data_size);
    memcpy(h+8, "WAVE", 4);
    memcpy(h+12, "fmt ", 4);
    put_le32(h+16, 16);
    put_le16(h+20, 1);            /* PCM */
    put_le16(h+22, channels);
    put_le32(h+24, rate);
    put_le32(h+28, rate * channels * (bits/8));
    put_le16(h+32, (uint16_t)(channels * (bits/8)));
    put_le16(h+34, bits);
    memcpy(h+36, "data", 4);
    put_le32(h+40, data_size);
}

static int wav_parse(const uint8_t *w, size_t len, unsigned *rate, unsigned *channels, unsigned *bits, size_t *data_off, size_t *data_len)
{
    if (len < 44) return -1;
    if (memcmp(w, "RIFF", 4) || memcmp(w+8, "WAVE", 4)) return -1;
    /* 只处理标准 44 字节布局的 fmt/data，云端 TTS 就是这个格式 */
    if (memcmp(w+12, "fmt ", 4)) return -1;
    if (get_le16(w+20) != 1) return -1;   /* 只支持 PCM */
    *channels = get_le16(w+22);
    *rate = get_le32(w+24);
    *bits = get_le16(w+34);
    if (memcmp(w+36, "data", 4)) return -1;
    *data_len = get_le32(w+40);
    *data_off = 44;
    if (*data_off + *data_len > len) *data_len = len - *data_off;  /* 容错 */
    return 0;
}
```

